{
  "case_id": "xsu_sg_007_work_stopped_due_to_impairment",
  "criteria": {
    "c01_overall_legal_correctness": {"label": "met", "reason": "Konklusionen (ophør i arbejde giver ikke i sig selv ret) og beskrivelsen af UDK's vurdering stemmer med rubrikken og vejledningens afsnit 3.4.1.3. Ingen væsentlige juridiske fejl."},
    "c02_required_elements_complete": {"label": "met", "reason": "Svaret dækker alle tre kritiske elementer: arbejdets karakter holdes op mod funktionsnedsættelsen, sagens øvrige oplysninger bruges til at vurdere andre typer arbejde, og skånehensyn eller mindre omfang indgår."},
    "c03_direct_relevance": {"label": "met", "reason": "Svaret besvarer begge dele af spørgsmålet: om arbejdsophør i sig selv giver ret (nej), og hvad Udbetaling Danmark vurderer."},
    "c04_source_traceability": {"label": "not_met", "reason": "Svaret angiver ingen identificerbar kilde, hverken lovbestemmelse, bekendtgørelse eller vejledningsafsnit."},
    "c05_source_validity": {"label": "not_assessable", "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."},
    "c06_claim_source_support": {"label": "not_assessable", "reason": "Der er ikke angivet nogen kilde, så det kan ikke vurderes, om kilden understøtter påstandene."},
    "c07_no_unsupported_legal_additions": {"label": "met", "reason": "Alle udsagn svarer til vejledningens afsnit 3.4.1.3. Svaret tilføjer ingen regler, betingelser eller myndigheder uden støtte."},
    "c08_qualifications_and_exceptions": {"label": "met", "reason": "Svaret bevarer, at arbejdsophør ikke i sig selv afgør retten, og at det er et udgangspunkt for en vurdering. Ikke-fysisk belastende arbejde er formuleret som et eksempel ('eksempelvis') og ikke som en selvstændig betingelse."},
    "c09_reasoning_coherence": {"label": "met", "reason": "Konklusionen følger af den beskrevne vurdering: der ses på arbejdets karakter og på muligheden for andet arbejde. Der er ingen indre modsigelser."},
    "c10_legal_modality_precision": {"label": "met", "reason": "Formuleringerne 'vurderer', 'kan', 'eventuelt' og 'eksempelvis' gengiver vejledningens skønsprægede modalitet. Intet gøres absolut."}
  },
  "xhaile_coverage": {
    "A22": {"label": "yes", "reason": "Svaret behandler situationen, hvor ansøger er stoppet i arbejde på grund af funktionsnedsættelsen, og at der så ses på arbejdets karakter i forhold til funktionsnedsættelsen."},
    "A23": {"label": "yes", "reason": "Svaret nævner, at Udbetaling Danmark vurderer, om ansøgeren ud fra sagens øvrige oplysninger kan varetage andre typer arbejde, eventuelt med skånehensyn eller i mindre omfang, samt gener og skånebehov."}
  },
  "overall_notes": "Indholdet er juridisk korrekt og fuldstændigt i forhold til rubrikken, men svaret citerer ingen kilde. Derfor er C04 not_met, og C05 og C06 er not_assessable."
}

